import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:share_plus/share_plus.dart';
import '../../../core/constants.dart';
import '../../../core/providers.dart';
import '../../../core/widgets/common.dart';
import '../../../core/theme/app_theme.dart';

class ReportsScreen extends ConsumerWidget{const ReportsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final bills=ref.watch(hydratedBillsProvider),custom=ref.watch(customBillsProvider).valueOrNull??const <Map<String,dynamic>>[];final active=bills.where((b)=>b['status']!='closed').toList();final totalDue=active.fold<double>(0,(v,b)=>v+(b['total_due'] as num).toDouble());final totalPaid=active.fold<double>(0,(v,b)=>v+(b['total_paid'] as num).toDouble());final pending=active.fold<double>(0,(v,b)=>v+(b['pending'] as num).toDouble());final payments=<Map<String,dynamic>>[];for(final b in [...bills,...custom]){for(final raw in (b['payments'] as List? ?? const [])){payments.add({'bill_no':b['bill_no'],'name':b['name'],'mobile':b['mobile'],...Map<String,dynamic>.from(raw as Map)});}}payments.sort((a,b)=>'${b['payment_date']??b['date']??''}'.compareTo('${a['payment_date']??a['date']??''}'));return Scaffold(appBar:AppBar(title:const Text('Reports'),actions:[IconButton(onPressed:()=>_export(payments),icon:const Icon(Icons.download_outlined))]),body:ListView(padding:const EdgeInsets.all(18),children:[GridView.count(crossAxisCount:2,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisSpacing:10,mainAxisSpacing:10,childAspectRatio:1.55,children:[StatCard(label:'Active rental charges',value:moneyLabel(totalDue),icon:Icons.receipt_long_outlined),StatCard(label:'Payments received',value:moneyLabel(totalPaid),icon:Icons.payments_outlined,color:AppColors.green),StatCard(label:'Balance pending',value:moneyLabel(pending),icon:Icons.pending_actions,color:AppColors.red),StatCard(label:'Custom bills',value:'${custom.length}',icon:Icons.shopping_bag_outlined)]),const SectionTitle('Payments received'),if(payments.isEmpty)const EmptyState(title:'No payments yet',description:'Recorded payments will appear here.')else ...payments.take(100).map((p)=>Card(margin:const EdgeInsets.only(bottom:8),child:ListTile(leading:const Icon(Icons.arrow_downward,color:AppColors.green),title:Text('${p['name']??'Customer'} · ${moneyLabel(p['amount']??0)}'),subtitle:Text('Bill #${p['bill_no']} · ${p['payment_date']??p['date']??''} · ${p['method']??''}')))),const SectionTitle('Material rent currently active'),...materialCatalog.map((s){final amount=active.fold<double>(0,(v,b){final cycles=(b['cycles'] as List? ?? const []).cast<Map>();final current=cycles.isEmpty?null:cycles.last;final qty=(current?['snapshot_qty'] as Map?)?[s.key]??b[s.quantityField]??0;return v+(qty is num?qty.toDouble():0)*(b[s.rateField] is num?(b[s.rateField] as num).toDouble():s.defaultRate);});final count=active.fold<int>(0,(v,b)=>v+((b['balance_qty'] as Map?)?[s.key] as num? ?? 0).toInt());return Card(child:ListTile(title:Text(s.label),subtitle:Text('$count currently out'),trailing:Text(moneyLabel(amount),style:const TextStyle(fontWeight:FontWeight.w800))));})]));}}
Future<void> _export(List<Map<String,dynamic>> rows)async{final quote=(Object? x)=>'"${'$x'.replaceAll('"','""')}"';final csv=['Date,Bill,Customer,Mobile,Amount,Method,Note',...rows.map((r)=>[r['payment_date']??r['date'],r['bill_no'],r['name'],r['mobile'],r['amount'],r['method'],r['note']].map(quote).join(','))].join('\n');await SharePlus.instance.share(ShareParams(text:csv,subject:'S.A Traders payment report CSV'));}
